<?php
session_start();require_once __DIR__.'/../koneksi.php';require_once __DIR__.'/../includes/auth.php';require_once __DIR__.'/../includes/legacy_activation.php';
requireRole(['admin','kasir']);
if(unit_all_readonly()){http_response_code(409);exit('Pilih SD, SMP, atau SMA di sidebar untuk aktivasi siswa Legacy.');}
if(empty($_SESSION['csrf_legacy_activation']))$_SESSION['csrf_legacy_activation']=bin2hex(random_bytes(32));
$id=(int)($_POST['id']??$_GET['id']??0);$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
    if(!is_string($_POST['csrf_token']??null)||!hash_equals($_SESSION['csrf_legacy_activation'],$_POST['csrf_token'])){http_response_code(403);exit('Token CSRF tidak valid.');}
    try{if(array_key_exists('pangkal',$_POST))throw new RuntimeException('Formulir aktivasi kedaluwarsa; muat ulang halaman.');if(($_POST['confirmed']??'')!=='1')throw new RuntimeException('Konfirmasikan tahun, kelas, dan tarif operasional.');legacy_activate($koneksi,$id,(int)($_POST['class_id']??0),(int)($_POST['year_id']??0),array_intersect_key($_POST,array_flip(['spp','psb','komite','du'])),(int)$_SESSION['admin_id'],(string)$_SESSION['admin_nama']);header('Location: daftar.php');exit;}catch(Throwable $e){http_response_code(409);$error=$e instanceof mysqli_sql_exception?'Aktivasi dibatalkan; periksa status dan relasi siswa.':$e->getMessage();}
}elseif($_SERVER['REQUEST_METHOD']!=='GET'){http_response_code(405);exit;}
$s=$koneksi->prepare('SELECT s.*,m.source_class,m.source_name,m.raw_data FROM siswa s JOIN legacy_student_import m ON m.student_id=s.id WHERE s.id=?');$s->bind_param('i',$id);$s->execute();$student=$s->get_result()->fetch_assoc();$s->close();if(!$student){http_response_code(404);exit('Siswa Legacy tidak ditemukan pada unit ini.');}
$classes=class_all($koneksi,true,false);$years=$koneksi->query("SELECT id,label,status FROM tahun_ajaran WHERE status IN ('published','draft') ORDER BY label='".du_current_academic_year()."' DESC,status='published' DESC,label DESC")->fetch_all(MYSQLI_ASSOC);
$rates=[];foreach($years as $year)foreach($classes as $class)$rates[$year['id']][$class['id']]=spp_current_effective_rate($koneksi,(string)$class['tingkat'],0,$year['label']);
function la_e($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
