<?php include __DIR__.'/../includes/sidebar.php'; ?><main class="main-content dbt-main"><div class="topbar"><button class="sidebar-toggle" onclick="toggleSidebar()" id="btn-sidebar-toggle" aria-label="Buka menu">☰</button><div class="topbar-title"><h2>Aktifkan &amp; Tempatkan</h2><span class="breadcrumb">Data Siswa / Legacy</span></div><div class="clock-badge" id="liveClock">--:--:--</div></div><div class="db-tools-page"><section class="dbt-card"><h2><?= la_e($student['NAMA']) ?> · <?= la_e($student['NO_INDUK']) ?></h2><p>Kelas sumber: <strong><?= la_e($student['source_class']) ?></strong> · <?= la_e($student['source_name']) ?></p><p>Tarif sumber (informasi, tidak diterapkan): <?php $raw=json_decode($student['raw_data'],true);foreach(['SPP_PERBULAN','POMG','DAFTAR_ULANG'] as $field): ?><?= la_e($field) ?> = <?= la_e($raw[$field]??'tidak tercatat') ?>; <?php endforeach; ?></p><p>Penempatan ini menjadi awal riwayat SistemSPP. Aktivasi tidak menerbitkan tagihan atau membuat rekening Tabungan.</p><?php if($error): ?><div class="dbt-warning" role="alert"><?= la_e($error) ?></div><?php endif; ?>
<?php if($student['legacy_pending']): ?><form method="post" id="legacy-activation"><input type="hidden" name="id" value="<?= $id ?>"><input type="hidden" name="csrf_token" value="<?= la_e($_SESSION['csrf_legacy_activation']) ?>"><div class="dbt-import-grid"><div><label for="class-id">Kelas/rombel aktif</label><select name="class_id" id="class-id" required><option value="">Pilih rombel</option><?php foreach($classes as $c): ?><option value="<?= $c['id'] ?>"><?= la_e($c['label']) ?></option><?php endforeach; ?></select></div><div><label for="year-id">Tahun ajaran yang dikonfirmasi</label><select name="year_id" id="year-id" required><?php foreach($years as $y): ?><option value="<?= $y['id'] ?>"><?= la_e($y['label'].' · '.$y['status']) ?></option><?php endforeach; ?></select></div></div><p id="legacy-rate-status" role="status">Pilih rombel untuk melihat tarif master.</p><div class="dbt-import-grid"><?php foreach(['spp'=>'SPP sesuai master','psb'=>'PSB','komite'=>'Komite per bulan','du'=>'Daftar Ulang'] as $key=>$label): ?><div><label for="fee-<?= $key ?>"><?= $label ?> (Rp)</label><input id="fee-<?= $key ?>" name="<?= $key ?>" type="number" min="0" step="0.01" value="0" required <?= $key==='spp'?'readonly':'' ?>></div><?php endforeach; ?></div><label><input type="checkbox" name="confirmed" value="1" required> Saya mengonfirmasi tahun, rombel, dan tarif operasional ini.</label><p><button class="btn btn-primary" type="submit">Aktifkan &amp; Tempatkan</button> <a class="btn btn-ghost" href="daftar.php?status=legacy">Batal</a></p></form><?php else: ?><p>Siswa telah diaktifkan; kiriman ulang tidak membuat penempatan.</p><?php endif; ?></section></div></main></div><script id="legacy-rates" type="application/json"><?= json_encode($rates,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_QUOT|JSON_HEX_APOS) ?></script><script src="../assets/js/date_format.js?v=<?= filemtime(__DIR__ . '/../assets/js/date_format.js') ?>"></script>
